(()=>{const d=document,root=d.documentElement,body=d.body,progress=d.querySelector('.progress'),glow=d.querySelector('.cursor-glow'),burger=d.querySelector('.burger'),nav=d.querySelector('.nav'),modal=d.querySelector('.modal');const prefersReduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function splitTitles(){d.querySelectorAll('.split-title').forEach(title=>{if(title.dataset.split)return;title.dataset.split='true';title.innerHTML=title.textContent.trim().split(/\s+/).map((w,i)=>`<span class="word"><span style="transition-delay:${Math.min(i*38,520)}ms">${w}</span></span>`).join(' ')})}function reveal(){const items=[...d.querySelectorAll('.reveal,.split-title')];if(!('IntersectionObserver'in window)||prefersReduced){items.forEach(x=>x.classList.add('in-view'));return}const io=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');io.unobserve(e.target)}})},{rootMargin:'0px 0px -8% 0px',threshold:.12});items.forEach(x=>io.observe(x))}function onScroll(){const max=root.scrollHeight-innerHeight;const p=max>0?scrollY/max*100:0;if(progress)progress.style.width=p+'%'}function moveGlow(e){if(!glow||prefersReduced)return;glow.animate({left:e.clientX+'px',top:e.clientY+'px'},{duration:650,fill:'forwards',easing:'cubic-bezier(.16,1,.3,1)'})}function magnetic(e){if(prefersReduced||innerWidth<1024)return;const t=e.currentTarget,r=t.getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;t.style.transform=`translate(${x*.14}px,${y*.18}px)`}function resetMag(e){e.currentTarget.style.transform=''}function openModal(){modal?.classList.add('active');body.classList.add('modal-open');modal?.setAttribute('aria-hidden','false')}function closeModal(){modal?.classList.remove('active');body.classList.remove('modal-open');modal?.setAttribute('aria-hidden','true')}function breakpointLabel(){const w=innerWidth;let label=w>=1600?'1920 desktop':w>=1024?'1200 laptop':w>=768?'768 tablet':'480 mobile';let node=d.querySelector('.resize-note');if(!node){node=d.createElement('div');node.className='resize-note';d.body.appendChild(node)}node.textContent=`Адаптив: ${label} • ${w}px`}splitTitles();reveal();onScroll();breakpointLabel();addEventListener('scroll',onScroll,{passive:true});addEventListener('pointermove',moveGlow,{passive:true});addEventListener('resize',breakpointLabel,{passive:true});burger?.addEventListener('click',()=>{body.classList.toggle('menu-open');burger.setAttribute('aria-expanded',body.classList.contains('menu-open'))});nav?.addEventListener('click',e=>{if(e.target.closest('a'))body.classList.remove('menu-open')});d.querySelectorAll('.magnetic,.btn').forEach(el=>{el.addEventListener('pointermove',magnetic);el.addEventListener('pointerleave',resetMag)});d.querySelectorAll('.modal-open').forEach(b=>b.addEventListener('click',openModal));d.querySelectorAll('.modal-close').forEach(b=>b.addEventListener('click',closeModal));modal?.addEventListener('click',e=>{if(e.target===modal)closeModal()});addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();body.classList.remove('menu-open')}});d.querySelectorAll('form').forEach(f=>f.addEventListener('submit',e=>e.preventDefault()))})();